import{_ as t,o as s,c as a,aj as i}from"./framework.js";const y=JSON.parse('{"title":"Style | Css | Template Engine","description":"Style in Kooboo: Routed .css resources for global themes, patches, and Layout head references.","frontmatter":{"title":"Style | Css | Template Engine","description":"Style in Kooboo: Routed .css resources for global themes, patches, and Layout head references.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/templateEngine/css/index.html"}]]},"headers":[],"relativePath":"templateEngine/css/index.md","filePath":"en/templateEngine/css/index.md","lastUpdated":1781010536000}'),o={name:"templateEngine/css/index.md"};function l(r,e,d,n,h,c){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="style" tabindex="-1">Style <a class="header-anchor" href="#style" aria-label="Permalink to &quot;Style&quot;">​</a></h1><blockquote><p>Routed <code>.css</code> resources for global themes, patches, and Layout <code>&lt;head&gt;</code> references.</p></blockquote><h2 id="what-it-is" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What It Is&quot;">​</a></h2><p><strong>Style</strong> is a separately stored CSS file in a Kooboo site. Once registered, it is available through a <strong>URL</strong> such as <code>/assets/site.css</code>. Use it for site-wide themes, component-library patches, or styles that should not live inside each individual Page.</p><p>It is managed by <strong><code>k.site.styles</code></strong>. See <a href="/kb-docs/api/site/css.html">k.site.styles</a>.</p><h2 id="referencing-it-in-templates" tabindex="-1">Referencing It in Templates <a class="header-anchor" href="#referencing-it-in-templates" aria-label="Permalink to &quot;Referencing It in Templates&quot;">​</a></h2><p>Inside the <code>&lt;head&gt;</code> of a Layout, or in a Page when needed:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stylesheet&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/assets/site.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>The <code>href</code> is the public path of the Style resource. On the server, <code>k.site.styles.getUrl(id)</code> returns the relative URL.</p><h2 id="style-vs-tailwind-vs-inline-css" tabindex="-1">Style vs Tailwind vs Inline CSS <a class="header-anchor" href="#style-vs-tailwind-vs-inline-css" aria-label="Permalink to &quot;Style vs Tailwind vs Inline CSS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Approach</th><th>Notes</th></tr></thead><tbody><tr><td>Tailwind CDN</td><td>Commonly loaded in a Layout with <code>https://www.kooboo.com/tailwindcss.js</code>, then utility classes are written directly in HTML</td></tr><tr><td>Style resource</td><td>Good for complex animation, global variables, and third-party component patches such as Element Plus plus Tailwind specificity fixes</td></tr><tr><td><code>&lt;style&gt;</code> inside a Page or View</td><td>Best when the rule only affects one page or one isolated fragment</td></tr></tbody></table><p>For most layout-oriented styling, prefer Tailwind first. Use a Style resource for rules that repeat, need central maintenance, or are awkward to keep inline.</p><h2 id="symmetry-with-script" tabindex="-1">Symmetry with Script <a class="header-anchor" href="#symmetry-with-script" aria-label="Permalink to &quot;Symmetry with Script&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Style</th><th>Script</th></tr></thead><tbody><tr><td>Tag</td><td><code>&lt;link rel=&quot;stylesheet&quot;&gt;</code></td><td><code>&lt;script src=&quot;...&quot;&gt;</code></td></tr><tr><td>Common location</td><td>Layout <code>&lt;head&gt;</code></td><td>Layout <code>&lt;head&gt;</code> or near the end of a Page</td></tr><tr><td>API</td><td><code>k.site.styles</code></td><td><code>k.site.scripts</code></td></tr></tbody></table><p>Both support routed URLs and version history. Layout and View resources do <strong>not</strong> have standalone URLs.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../layout/">Layout</a></li><li><a href="./../js/">Script</a></li><li><a href="/kb-docs/api/site/css.html">k.site.styles</a></li></ul>',17)])])}const u=t(o,[["render",l]]);export{y as __pageData,u as default};
